20	IntersectFile::IntersectFile(ContextIntersect *context)
21	: ToolBase(upCast(context)),
22	  _sweep(NULL),
23	  _binTree(NULL),
24	  _queryFRM(NULL)
25	{
26	
27	}
28	
29	IntersectFile::~IntersectFile(void) {
30		delete _sweep;
31		_sweep = NULL;
32	
33		delete _binTree;
34		_binTree = NULL;
35	}
36	
37	bool IntersectFile::init() {
38	
39		_queryFRM = upCast(_context)->getFile(upCast(_context)->getQueryFileIdx());
40	
41		 if (upCast(_context)->getSortedInput()) {
42			 makeSweep();
43			return _sweep->init();
44		 } else {
45			_binTree = new BinTree( upCast(_context));
46			_binTree->loadDB();
47		 }
48	
49		 return true;
50	}
51	
52	bool IntersectFile::findNext(RecordKeyVector &hits)
53	{
54		 bool retVal = false;
55		 if (upCast(_context)->getSortedInput()) {
56			retVal = nextSortedFind(hits);
57		 } 
58		 else {
59			retVal = nextUnsortedFind(hits);
60		 }
61	
62		 if (retVal) {
63			 checkSplits(hits);
64		 }
65		 return retVal;
66	}
67	
68	void IntersectFile::processHits(RecordOutputMgr *outputMgr, RecordKeyVector &hits)
69	{
70		outputMgr->printRecord(hits);
71	}
72	
73	void IntersectFile::cleanupHits(RecordKeyVector &hits)
74	{
75		_queryFRM->deleteRecord(hits.getKey());
76		hits.clearAll();
77	}
78	
79	bool IntersectFile::finalizeCalculations()
80	{
81	    if (upCast(_context)->getSortedInput() && !upCast(_context)->hasGenomeFile()) 
82	    {
83	        if (_context->getNameCheckDisabled())
84	            _sweep->closeOut(false);
85	        else
86	            _sweep->closeOut(true);
87	    }
88	    return true;
89	}
90	
91	bool IntersectFile::nextSortedFind(RecordKeyVector &hits)
92	{
93	    if (!_sweep->next(hits)) {
94	    	return false;
95	    }
96	    return true;
97	}
98	
99	bool IntersectFile::nextUnsortedFind(RecordKeyVector &hits)
100	{
101	
102		while (!_queryFRM->eof()) {
103			Record *queryRecord = _queryFRM->getNextRecord();
104			if (queryRecord == NULL) {
105				continue;
106			} else {
107				_context->testNameConventions(queryRecord);
108				hits.setKey(queryRecord);
109				 _binTree->getHits(queryRecord, hits);
110				return true;
111			}
112		}
113		return false;
114	}
115	
116	void IntersectFile::makeSweep() {
117		_sweep = new NewChromSweep(upCast(_context));
118	}
119	
120	void IntersectFile::checkSplits(RecordKeyVector &hitSet)
121	{
122		if (upCast(_context)->getObeySplits()) {
123			RecordKeyVector keySet(hitSet.getKey());
124			RecordKeyVector resultSet(hitSet.getKey());
125			upCast(_context)->getSplitBlockInfo()->findBlockedOverlaps(keySet, hitSet, resultSet);
126			hitSet.swap(resultSet);
127		}
128	}
