22	
23	// define our program name
24	#define PROGRAM_NAME "getOverlap"
25	
26	// define our parameter checking macro
27	#define PARAMETER_CHECK(param, paramLen, actualLen) (strncmp(argv[i], param, min(actualLen, paramLen))== 0) && (actualLen == paramLen)
28	
29	
30	// function declarations
31	void getoverlap_help(void);
32	void DetermineInput(string &inFile, short &s1Col, short &e1Col, short &s2Col, short &e2Col);
33	void ComputeOverlaps(istream &input, short &s1Col, short &e1Col, short &s2Col, short &e2Col);
34	
35	int getoverlap_main(int argc, char* argv[]) {
36	
37	    // input files
38	    string inFile = "stdin";
39	    string columns;
40	
41	    // our configuration variables
42	    bool showHelp = false;
43	    bool haveInFile  = true;
44	    bool haveColumns = false;
45	
46	
47	    for(int i = 1; i < argc; i++) {
48	        int parameterLength = (int)strlen(argv[i]);
49	
50	        if((PARAMETER_CHECK("-h", 2, parameterLength)) ||
51	        (PARAMETER_CHECK("--help", 5, parameterLength))) {
52	            showHelp = true;
53	        }
54	    }
55	
56	    if(showHelp) getoverlap_help();
57	
58	    // do some parsing (all of these parameters require 2 strings)
59	    for(int i = 1; i < argc; i++) {
60	
61	        int parameterLength = (int)strlen(argv[i]);
62	
63	        if(PARAMETER_CHECK("-i", 2, parameterLength)) {
64	            if ((i+1) < argc) {
65	                inFile     = argv[i + 1];
66	                i++;
67	            }
68	        }
69	        else if(PARAMETER_CHECK("-cols", 5, parameterLength)) {
70	            haveColumns = true;
71	            columns     = argv[i + 1];
72	            i++;
73	        }
74	        else {
75	            cerr << endl << "*****ERROR: Unrecognized parameter: " << argv[i] << " *****" << endl << endl;
76	            showHelp = true;
77	        }
78	    }
79	
80	    // make sure we have an input files
81	    if (!haveInFile ) {
82	        cerr << endl << "*****" << endl << "*****ERROR: Need -i file. " << endl << "*****" << endl;
83	        showHelp = true;
84	    }
85	
86	    if (!showHelp) {
87	
88	        // Split the column string sent by the user into discrete column numbers
89	        // A comma separated string is expected.
90	        vector<string> posColumns;
91	        Tokenize(columns, posColumns, ',');
92	
93	        if (posColumns.size() != 4) {
94	            cerr << endl << "*****" << endl << "*****ERROR: Please specify 4, comma-separated position columns. " << endl << "*****" << endl;
95	            getoverlap_help();
96	        }
97	        else {
98	            short s1, e1, s2, e2;
99	            s1 = atoi(posColumns[0].c_str());
100	            e1 = atoi(posColumns[1].c_str());
101	            s2 = atoi(posColumns[2].c_str());
102	            e2 = atoi(posColumns[3].c_str());
103	
104	            DetermineInput(inFile, s1, e1, s2, e2);
105	        }
106	    }
107	    else {
108	        getoverlap_help();
109	    }
110	    return 0;
111	}
112	
113	void getoverlap_help(void) {
114	
115	    cerr << "\nTool:    bedtools overlap (aka getOverlap)" << endl;
116	    cerr << "Version: " << VERSION << "\n";    
117	    cerr << "Summary: Computes the amount of overlap (positive values)" << endl;
118	    cerr << "\t or distance (negative values) between genome features" << endl;
119	    cerr << "\t and reports the result at the end of the same line." << endl << endl;
120	
121	    cerr << "Options: " << endl;
122	    cerr << "\t-i\t"        << "Input file. Use \"stdin\" for pipes." << endl << endl;
123	
124	    cerr << "\t-cols\t"     << "Specify the columns (1-based) for the starts and ends of the" << endl;
125	    cerr                    << "\t\tfeatures for which you'd like to compute the overlap/distance." << endl;
126	    cerr                    << "\t\tThe columns must be listed in the following order: " << endl << endl;
127	    cerr                    << "\t\tstart1,end1,start2,end2" << endl << endl;
128	
129	    cerr << "Example: " << endl;
130	    cerr << "\t$ windowBed -a A.bed -b B.bed -w 10" << endl;
131	    cerr << "\tchr1 10  20  A   chr1    15  25  B" << endl;
132	    cerr << "\tchr1 10  20  C   chr1    25  35  D" << endl << endl;
133	    cerr << "\t$ windowBed -a A.bed -b B.bed -w 10 | overlap -i stdin -cols 2,3,6,7" << endl;
134	    cerr << "\tchr1 10  20  A   chr1    15  25  B   5" << endl;
135	    cerr << "\tchr1 10  20  C   chr1    25  35  D   -5" << endl;
136	
137	    // end the program here
138	    exit(1);
139	
140	}
141	
142	
143	void DetermineInput(string &inFile, short &s1Col, short &e1Col, short &s2Col, short &e2Col) {
144	
145	
146	    if (inFile != "stdin") {   // process a file
147	
148	        ifstream in(inFile.c_str(), ios::in);
149	        if ( !in ) {
150	            cerr << "Error: The requested input file (" << inFile << ") could not be opened. Exiting!" << endl;
151	            exit (1);
152	        }
153	        ComputeOverlaps(in, s1Col, e1Col, s2Col, e2Col);
154	    }
155	    else ComputeOverlaps(cin, s1Col, e1Col, s2Col, e2Col);
156	}
157	
158	
159	void ComputeOverlaps(istream &input, short &s1Col, short &e1Col, short &s2Col, short &e2Col) {
160	
161	    int lineNum = 0;
162	    string inLine;
163	    vector<string> inFields;
164	
165	    CHRPOS overlap;
166	
167	    char *s1End, *e1End, *s2End, *e2End;
168	    long s1, e1, s2, e2;
169	
170	    while (getline(input, inLine)) {
171	        lineNum++;
172	        Tokenize(inLine, inFields);
173	
174	        if (inFields.size() > 1) {
175	
176	            // test if columns  2 and 3 are integers.  If so, assume BED.
177	            s1 = strtol(inFields[s1Col-1].c_str(), &s1End, 10);
178	            e1 = strtol(inFields[e1Col-1].c_str(), &e1End, 10);
179	            s2 = strtol(inFields[s2Col-1].c_str(), &s2End, 10);
180	            e2 = strtol(inFields[e2Col-1].c_str(), &e2End, 10);
181	
182	            // strtol will set pointers to the start of the string if non-integral, base 10
183	            // if they all check out, we have valid numeric columns.  Otherwise, complain.
184	            if (s1End != inFields[s1Col-1].c_str() &&
185	                e1End != inFields[e1Col-1].c_str() &&
186	                s2End != inFields[s2Col-1].c_str() &&
187	                e2End != inFields[e2Col-1].c_str()) {
188	
189	                overlap = overlaps(s1, e1, s2, e2);
190	                printf("%s\t%" PRId_CHRPOS "\n", inLine.c_str(), overlap);
191	            }
192	            else {
193	                cerr << "One of your columns appears to be non-numeric at line " << lineNum << ". Exiting..." << endl << endl;
194	                exit(1);
195	            }
196	        }
197	        inFields.clear();
198	    }
199	}
