21	bool ContextIntersect::parseCmdArgs(int argc, char **argv, int skipFirstArgs) {
22		for (_i=_skipFirstArgs; _i < argc; _i++) {
23			if (isUsed(_i - _skipFirstArgs)) {
24				continue;
25			}
26			if (strcmp(_argv[_i], "-a") == 0) {
27				if (!handle_a()) return false;
28			}
29	        else if (strcmp(_argv[_i], "-abam") == 0) {
30				if (!handle_abam()) return false;
31	        }
32	        else if (strcmp(_argv[_i], "-b") == 0) {
33				if (!handle_b()) return false;
34			}
35	        else if (strcmp(_argv[_i], "-names") == 0) {
36				if (!handle_names()) return false;
37			}
38	        else if (strcmp(_argv[_i], "-filenames") == 0) {
39				if (!handle_filenames()) return false;
40			}
41	        else if (strcmp(_argv[_i], "-u") == 0) {
42				if (!handle_u()) return false;
43	        }
44	        else if (strcmp(_argv[_i], "-f") == 0) {
45				if (!handle_f()) return false;
46	        }
47	        else if (strcmp(_argv[_i], "-F") == 0) {
48				if (!handle_F()) return false;
49	        }
50	        else if (strcmp(_argv[_i], "-wa") == 0) {
51				if (!handle_wa()) return false;
52	        }
53	        else if (strcmp(_argv[_i], "-wao") == 0) {
54				if (!handle_wao()) return false;
55	        }
56	        else if (strcmp(_argv[_i], "-wb") == 0) {
57				if (!handle_wb()) return false;
58	        }
59	        else if (strcmp(_argv[_i], "-wo") == 0) {
60				if (!handle_wo()) return false;
61	        }
62	        else if (strcmp(_argv[_i], "-c") == 0) {
63				if (!handle_c()) return false;
64	        }
65	        else if(strcmp(_argv[_i], "-r") == 0) {
66				if (!handle_r()) return false;
67	        }
68	        else if(strcmp(_argv[_i], "-e") == 0) {
69				if (!handle_e()) return false;
70	        }
71	        else if (strcmp(_argv[_i], "-v") == 0) {
72				if (!handle_v()) return false;
73	        }
74	        else if (strcmp(_argv[_i], "-s") == 0) {
75				if (!handle_s()) return false;
76	        }
77	        else if (strcmp(_argv[_i], "-S") == 0) {
78				if (!handle_S()) return false;
79	        }
80	        else if (strcmp(_argv[_i], "-loj") == 0) {
81				if (!handle_loj()) return false;
82	        }
83		}
84		return ContextBase::parseCmdArgs(argc, argv, _skipFirstArgs);
85	}
