89	bool ContextIntersect::isValidState()
90	{
91		if (!ContextBase::isValidState()) {
92			return false;
93		}
94	
95		if (_queryFileIdx == -1 || _dbFileIdxs.size() == -0) {
96			_errorMsg = "\n***** ERROR: query and database files not specified. *****";
97			return false;
98		}
99	
100		if (getAnyHit() && getNoHit()) {
101			_errorMsg = "\n***** ERROR: request either -u for anyHit OR -v for noHit, not both. *****";
102			return false;
103		}
104		if (getWriteCount()) {
105			if (getAnyHit()) {
106				_errorMsg = "\n***** ERROR: request either -c for writeCount OR -u for anyHit, not both. *****";
107				return false;
108			}  else if (getWriteB()) {
109				_errorMsg = "\n***** ERROR: request either -c for writeCount OR -wb for writeB, not both. *****";
110				return false;
111			} else if (getQueryFileType() == FileRecordTypeChecker::BAM_FILE_TYPE && !getExplicitBedOutput()) {
112				_errorMsg = "\n***** ERROR: writeCount option is not valid with BAM query input, unless bed output is specified with -bed option. *****";
113				return false;
114			}
115		}
116	
117		if (_haveFractionA && (_overlapFractionA <= 0.0 || _overlapFractionA > 1.0)) {
118			_errorMsg = "\n***** ERROR: -f must be in the range (0.0, 1.0]. *****";
119			return false;
120		}
121		if (_haveFractionB && (_overlapFractionB <= 0.0 || _overlapFractionB > 1.0)) {
122			_errorMsg = "\n***** ERROR: -F must be in the range (0.0, 1.0]. *****";
123			return false;
124		}
125		if (_haveFractionB && !_haveFractionA && _eitherFraction) {
126			_errorMsg = "\n***** ERROR: -e must be used with -f. *****";
127			return false;
128		}
129		if (_haveFractionB && _reciprocalFraction) {
130			_errorMsg = "\n***** ERROR: -r must be used solely with -f. *****";
131			return false;
132		}
133		if (_haveFractionA && _haveFractionB && _reciprocalFraction) {
134			_errorMsg = "\n***** ERROR: -r must be used solely with -f. *****";
135			return false;
136		}
137	
138		// if -f and -r are given, then we need to set _overlapFractionB to be the same as _overlapFractionA
139		if (_haveFractionA && _reciprocalFraction) {
140			setOverlapFractionB(_overlapFractionA);
141		}
142	
143		if (getUseDBnameTags() && _dbNameTags.size() != _dbFileIdxs.size()) {
144			_errorMsg = "\n***** ERROR: Number of database name tags given does not match number of databases. *****";
145			return false;
146	
147		}
148	
149	
150		if (getWriteOverlap()) {
151	
152			if (getWriteA()) {
153				_errorMsg = "\n***** ERROR: request either -wa for writeA OR -wo for writeOverlap, not both. *****";
154				return false;
155			} else if (getWriteB()) {
156				_errorMsg = "\n***** ERROR: request either -wb for writeB OR -wo for writeOverlap, not both. *****";
157				return false;
158			}  else if (getWriteCount()) {
159				_errorMsg = "\n***** ERROR: request either -c for writeCount OR -wo for writeOverlap, not both. *****";
160				return false;
161			} else if (getAnyHit()) {
162				_errorMsg = "\n***** ERROR: request either -u for anyHit OR -wo for writeOverlap, not both. *****";
163				return false;
164			} else if (getQueryFileType() == FileRecordTypeChecker::BAM_FILE_TYPE && !getExplicitBedOutput()) {
165				_errorMsg = "\n***** ERROR: writeAllOverlap option is not valid with BAM query input, unless bed output is specified with -bed option. *****";
166				return false;
167			}
168		}
169		if (getWriteB() || getLeftJoin()) {
170			if (getQueryFileType() == FileRecordTypeChecker::BAM_FILE_TYPE && !getExplicitBedOutput()) {
171				cerr << endl << "*****" << endl << "*****WARNING: -wb and -loj are ignored with bam input, unless bed output is specified with -bed option." << endl << "*****" << endl;
172			}
173		}
174		if (getSameStrand() && getDiffStrand()) {
175			_errorMsg = "\n***** ERROR: request -s for sameStrand, or -S for diffStrand, not both. *****";
176			return false;
177		}
178		if ((getSameStrand() || getDiffStrand()) && !strandedToolSupported()) {
179			//error msg set within strandedToolSupported method.
180			return false;
181		}
182	
183		if (getQueryFileType() == FileRecordTypeChecker::BAM_FILE_TYPE && getPrintHeader()) {
184			cerr << endl << "*****" << endl << "*****WARNING: -header option is not valid for BAM input." << endl << "*****" << endl;
185			setPrintHeader(false);
186		}
187		if (getAnyHit() || getNoHit() || getWriteCount()) {
188			setPrintable(false);
189		}
190	
191		if (getNoHit() || getWriteCount() || getWriteOverlap() 
192			|| getWriteAllOverlap() || getLeftJoin())
193		{
194			setRunToQueryEnd(true);
195		}
196	
197		if (_files.size()  < 2 ) {
198			return false;
199		}
200		return true;
201	}
