203	bool ContextIntersect::determineOutputType() {
204		if (_outputTypeDetermined) {
205			return true;
206		}
207	
208		//determine the maximum number of database fields.
209		for (int i=0; i < getNumDatabaseFiles(); i++) {
210			int numFields = getDatabaseFile(i)->getNumFields();
211			if ( numFields > _maxNumDatabaseFields) {
212				_maxNumDatabaseFields = numFields;
213			}
214		}
215		return ContextBase::determineOutputType();
216	}
