15	void GetBamBlocks(const BamAlignment &bam,
16	                  const string &chrom,
17	                  bedVector &bedBlocks,
18	                  bool breakOnDeletionOps,
19	                  bool breakOnSkipOps)
20	{
21	    vector<int> starts;
22	    vector<int> lengths;
23	    starts.push_back(0);
24	    
25	    string strand;
26	    bam.IsReverseStrand() ? strand = "-" : strand = "+";
27	    CHRPOS currPosition = bam.Position;
28	    int blockLength  = 0;
29	
30	    //  Rip through the CIGAR ops and figure out if there is more
31	    //  than one block for this alignment
32	    vector<CigarOp>::const_iterator cigItr = bam.CigarData.begin();
33	    vector<CigarOp>::const_iterator cigEnd = bam.CigarData.end();
34	    for (; cigItr != cigEnd; ++cigItr) {
35	        switch (cigItr->Type) {
36	            case ('M') :case ('X'): case ('='):
37	                blockLength += cigItr->Length;
38	            case ('I') : break;
39	            case ('S') : break;
40	            case ('D') :
41	                if (!breakOnDeletionOps)
42	                    blockLength += cigItr->Length;
43	                else {
44	                    bedBlocks.push_back( BED(chrom, currPosition, currPosition + blockLength,
45	                                          bam.Name, ToString(bam.MapQuality), strand) );
46	                    currPosition += cigItr->Length + blockLength;
47	                    blockLength = 0;
48	                }
49	            case ('P') : break;
50	            case ('N') :
51	                if (!breakOnSkipOps)
52	                    blockLength += cigItr->Length;
53	                else {
54	                    bedBlocks.push_back( BED(chrom, currPosition, currPosition + blockLength,
55	                                          bam.Name, ToString(bam.MapQuality), strand) );
56	                    currPosition += cigItr->Length + blockLength;
57	                    blockLength = 0;
58	                }
59	            case ('H') : break;                             // for 'H' - do nothing, move to next op
60	            default    :
61	                fprintf(stderr,"ERROR: Invalid Cigar op type \'%c\'.\n",cigItr->Type);   // shouldn't get here
62	                exit(1);
63	        }
64	    }
65	    bedBlocks.push_back( BED(chrom, currPosition, currPosition + blockLength,
66	                          bam.Name, ToString(bam.MapQuality), strand) );
67	}
68	
69	
70	void GetBedBlocks(const BED &bed, bedVector &bedBlocks) {
71	
72	    // nothing to do if it is not a BED12 intervals
73	    if (bed.fields.size() != 12) {
74	        bedBlocks.push_back(bed);
75	        return;
76	    }
77	
78	    int blockCount = atoi(bed.fields[9].c_str());
79	    if ( blockCount <= 0 ) {
80	        cerr << "Input error: found interval having <= 0 blocks." << endl;
81	        exit(1);
82	    }
83	    else if ( blockCount == 1 ) {
84	        //take a short-cut for single blocks
85	        bedBlocks.push_back(bed);
86	    }
87	    else {
88	        // get the comma-delimited strings for the BED12 block starts and block ends.
89	        string blockSizes(bed.fields[10]);
90	        string blockStarts(bed.fields[11]);
91	
92	        vector<CHRPOS> sizes;
93	        vector<CHRPOS> starts;
94	        Tokenize(blockSizes, sizes, ',');
95	        Tokenize(blockStarts, starts, ',');
96	
97	        if ( sizes.size() != (size_t) blockCount || starts.size() != (size_t) blockCount ) {
98	            cerr << "Input error: found interval with block-counts not matching starts/sizes on line." << endl;
99	            exit(1);
100	        }
101	
102	        // add each BED block to the bedBlocks vector
103	        for (UINT i = 0; i < (UINT) blockCount; ++i) {
104	            CHRPOS blockStart = bed.start + starts[i];
105	            CHRPOS blockEnd   = bed.start + starts[i] + sizes[i];
106	            BED currBedBlock(bed.chrom, blockStart, blockEnd, 
107	                             bed.name, bed.score, bed.strand, bed.fields, bed.other_idxs);
108	            bedBlocks.push_back(currBedBlock);
109	        }
110	    }
111	}
112	
113	
114	int GetTotalBlockLength(const bedVector &bedBlocks) {
115	    int total_size = 0;
116	    bedVector::const_iterator blockItr = bedBlocks.begin();
117	    bedVector::const_iterator blockEnd = bedBlocks.end();
118	    for (; blockItr != blockEnd; ++blockItr) {
119	        total_size += blockItr->end - blockItr->start;
120	    }
121	    return total_size;
122	}
