126	bool ContextBase::determineOutputType() {
127		if (_outputTypeDetermined) {
128			return true;
129		}
130		//test whether output should be BED or BAM.
131		//If the user explicitly requested BED, then it's BED.
132		if (getExplicitBedOutput()) {
133			setOutputFileType(FileRecordTypeChecker::SINGLE_LINE_DELIM_TEXT_FILE_TYPE);
134			_outputTypeDetermined = true;
135			return true;
136		}
137	
138		//Otherwise, if the input is BAM, then the output is BAM
139		int fileIdx = hasIntersectMethods() ? _queryFileIdx : 0;
140		if (_files[fileIdx]->getFileType() == FileRecordTypeChecker::BAM_FILE_TYPE) {
141			setOutputFileType(FileRecordTypeChecker::BAM_FILE_TYPE);
142			_isCram = _files[fileIdx]->isCram();
143			return true;
144		}
145	
146		//Okay, it's bed.
147		setOutputFileType(FileRecordTypeChecker::SINGLE_LINE_DELIM_TEXT_FILE_TYPE);
148		_outputTypeDetermined = true;
149		return true;
150	
151	
