178	bool ContextBase::parseCmdArgs(int argc, char **argv, int skipFirstArgs) {
179	
180	
181		for (_i=_skipFirstArgs; _i < argc; _i++) {
182			if (isUsed(_i - _skipFirstArgs)) {
183				continue;
184			}
185	
186			if (strcmp(_argv[_i], "-i") == 0) {
187				if (!handle_i()) return false;
188			}
189			else if (strcmp(_argv[_i], "-g") == 0) {
190				if (!handle_g()) return false;
191			}
192			else if ((strcmp(_argv[_i], "-h") == 0) || (strcmp(_argv[_i], "--help") == 0)) {
193				if (!handle_h()) return false;
194			}
195			else if (strcmp(_argv[_i], "-split") == 0) {
196				if (!handle_split()) return false;
197			}
198	        else if (strcmp(_argv[_i], "-bed") == 0) {
199				if (!handle_bed()) return false;
200	       }
201	        else if (strcmp(_argv[_i], "-ubam") == 0) {
202				if (!handle_ubam()) return false;
203	        }
204	        else if (strcmp(_argv[_i], "-fbam") == 0) {
205				if (!handle_fbam()) return false;
206	        }
207	        else if(strcmp(_argv[_i], "-sorted") == 0) {
208				if (!handle_sorted()) return false;
209	        }
210	        else if (strcmp(_argv[_i], "-nobuf") == 0) {
211				if (!handle_nobuf()) return false;
212	        }
213	        else if (strcmp(_argv[_i], "-iobuf") == 0) {
214				if (!handle_iobuf()) return false;
215	        }
216	        else if (strcmp(_argv[_i], "-prec") == 0) {
217				if (!handle_prec()) return false;
218	        }
219	        else if (strcmp(_argv[_i], "-header") == 0) {
220				if (!handle_header()) return false;
221	        }
222	        else if (strcmp(_argv[_i], "-n") == 0) {
223				if (!handle_n()) return false;
224	        }
225	        else if (strcmp(_argv[_i], "-seed") == 0) {
226				if (!handle_seed()) return false;
227	        }
228	        else if ((strcmp(_argv[_i], "-o") == 0) || (strcmp(_argv[_i], "-ops") == 0)) {
229				if (!handle_o()) return false;
230	        }
231	        else if ((strcmp(_argv[_i], "-c") == 0) || (strcmp(_argv[_i], "-opCols") == 0)) {
232				if (!handle_c()) return false;
233	        }
234	        else if (strcmp(_argv[_i], "-null") == 0) {
235				if (!handle_null()) return false;
236	        }
237	        else if (strcmp(_argv[_i], "-delim") == 0) {
238				if (!handle_delim()) return false;
239	        }
240	        else if (strcmp(_argv[_i], "-sortout") == 0) {
241				if (!handle_sortout()) return false;
242	        }
243	        else if (strcmp(_argv[_i], "-nonamecheck") == 0) {
244				if (!handle_nonamecheck()) return false;
245	        }
246	
247		}
248		return true;
249	}
