251	bool ContextBase::isValidState()
252	{
253		if (!openFiles()) {
254			return false;
255		}
256		if (!cmdArgsValid()) {
257			return false;
258		}
259		if (!determineOutputType()) {
260			return false;
261		}
262		if (_program != GROUP_BY && 
263			_files[0]->getRecordType() == FileRecordTypeChecker::NO_POS_PLUS_RECORD_TYPE) 
264		{
265			_errorMsg = "ERROR: file ";
266			_errorMsg.append(_files[0]->getFileName());
267			_errorMsg.append(" has non positional records, which are only valid for \n");
268			_errorMsg.append(" the groupBy tool. Perhaps you are using a header");
269			_errorMsg.append(" line(s) that starts with \n");
270			_errorMsg.append(" something other than \"#\", \"chrom\", or \"chr\" (any case)?");
271			return false;
272		}
273		if (getObeySplits()) {
274			_splitBlockInfo = new BlockMgr(_overlapFractionA, _reciprocalFraction);
275		}
276		if (hasColumnOpsMethods()) {
277	
278			if (hasIntersectMethods()) {
279				for (int i=0; i < (int)_dbFileIdxs.size(); i++) {
280					FileRecordMgr *dbFile = getFile(_dbFileIdxs[i]);
281					_keyListOps->setDBfileType(dbFile->getFileType());
282					if (!_keyListOps->isValidColumnOps(dbFile)) {
283						return false;
284					}
285				}
286			} else {
287				FileRecordMgr *dbFile = getFile(0);
288				_keyListOps->setDBfileType(dbFile->getFileType());
289				if (!_keyListOps->isValidColumnOps(dbFile)) {
290					return false;
291				}
292			}
293			//if user specified a precision, pass it to
294			//keyList ops
295			if (_reportPrecision != -1) {
296				_keyListOps->setPrecision(_reportPrecision);
297			}
298		}
299		return true;
300	}
