303	bool ContextBase::cmdArgsValid()
304	{
305		bool retval = true;
306		for (_i = _skipFirstArgs; _i < _argc; _i++) {
307			if (!isUsed(_i - _skipFirstArgs)) {
308				_errorMsg += "\n***** ERROR: Unrecognized parameter: ";
309				_errorMsg += _argv[_i];
310				_errorMsg += " *****";
311				retval = false;
312			}
313		}
314		return retval;
