317	bool ContextBase::openFiles() {
318	
319		//Make a vector of FileRecordMgr objects by going through the vector
320		//of filenames and opening each one.
321		if (_allFilesOpened) {
322			return true;
323		}
324	
325		if (_fileNames.size() == 0) {
326			//No input was specified. Error and exit.
327			_errorMsg += "\n***** ERROR: No input file given. Exiting. *****";
328			return false;
329		}
330	
331		_files.resize(_fileNames.size());
332	
333		for (int i = 0; i < (int)_fileNames.size(); i++) {
334			FileRecordMgr *frm = getNewFRM(_fileNames[i], i);
335			if (hasGenomeFile()) {
336				frm->setGenomeFile(_genomeFile);
337			}
338			//If we're going to do column operations, and an input file
339			// is BAM, we'll need the full flags.
340			if (hasColumnOpsMethods()) {
341				setUseFullBamTags(true);
342			}
343			frm->setFullBamFlags(_useFullBamTags);
344			frm->setIsSorted(_sortedInput);
345			frm->setIoBufSize(_ioBufSize);
346			frm->setIsGroupBy(_program == GROUP_BY);
347			if (!frm->open(_inheader)) {
348				return false;
349			}
350			if (_noEnforceCoordSort) {
351				frm->setNoEnforceCoordSort(true);
352			}
353			_files[i] = frm;
354		}
355		_allFilesOpened = true;
356		return true;
357	}
