359	int ContextBase::getBamHeaderAndRefIdx() {
360		if (_bamHeaderAndRefIdx != -1) {
361			//already found which BAM file to use for the header
362			return _bamHeaderAndRefIdx;
363		}
364		if (hasIntersectMethods()) {
365			if (_files[_queryFileIdx]->getFileType() == FileRecordTypeChecker::BAM_FILE_TYPE) {
366				_bamHeaderAndRefIdx = _queryFileIdx;
367			} else {
368				_bamHeaderAndRefIdx = _dbFileIdxs[0];
369			}
370			return _bamHeaderAndRefIdx;
371		}
372		if (_files[0]->getFileType() == FileRecordTypeChecker::BAM_FILE_TYPE) {
373			_bamHeaderAndRefIdx = 0;
374			return _bamHeaderAndRefIdx;
375		}
376	
377		return _bamHeaderAndRefIdx;
378	}
