648	bool ContextBase::parseIoBufSize(string bufStr)
649	{
650		char lastChar = bufStr[bufStr.size()-1];
651		int multiplier = 1;
652		if (!isdigit(lastChar)) {
653			switch (lastChar) {
654			case 'K':
655				multiplier = 1 << 10;
656				break;
657			case 'M':
658				multiplier = 1 << 20;
659				break;
660			case 'G':
661				multiplier = 1 << 30;
662				break;
663			default:
664				_errorMsg = "\n***** ERROR: Unrecognized memory buffer size suffix \'";
665				_errorMsg += lastChar;
666				_errorMsg += "\' given. *****";
667				return false;
668				break;
669			}
670			//lop off suffix character
671			bufStr.resize(bufStr.size()-1);
672		}
673		if (!isNumeric(bufStr)) {
674			_errorMsg = "\n***** ERROR: argument passed to -iobuf is not numeric. *****";
675			return false;
676		}
677		_ioBufSize = (int)str2chrPos(bufStr) * multiplier;
678		if (_ioBufSize < MIN_ALLOWED_BUF_SIZE) {
679			_errorMsg = "\n***** ERROR: specified buffer size is too small. *****";
680			return false;
681		}
682		return true;
683	}
