685	void ContextBase::testNameConventions(const Record *record) {
686		//Do nothing if using the -nonamecheck option,
687		//warning already given, or record is unmapped BAM record
688		if (getNameCheckDisabled() || _nameConventionWarningTripped || record->isUnmapped()) return;
689	
690		int fileIdx = record->getFileIdx();
691	
692		//
693		// First test whether chr in chrom names match
694		//
695	
696		bool hasChr = record->hasChrInChromName();
697		testType testChrVal = fileHasChrInChromNames(fileIdx);
698	
699		if (testChrVal == UNTESTED) {
700			_fileHasChrInChromNames[fileIdx] = hasChr ? YES : NO;
701		}
702		if ((_allFilesHaveChrInChromNames == YES && !hasChr) || (_allFilesHaveChrInChromNames == NO && hasChr)) {
703			nameConventionWarning(record, _fileNames[fileIdx], " has inconsistent naming convention for record:\n");
704		}
705	
706		if (_allFilesHaveChrInChromNames == UNTESTED) {
707			_allFilesHaveChrInChromNames = hasChr ? YES : NO;
708		}
709	
710	
711		//
712		// Now test whether leading zero in chrom names match
713		//
714	
715	
716		bool zeroVal = record->hasLeadingZeroInChromName(hasChr);
717		testChrVal = fileHasLeadingZeroInChromNames(fileIdx);
718		if (testChrVal == UNTESTED) {
719			_fileHasLeadingZeroInChromNames[fileIdx] = zeroVal ? YES : NO;
720		}
721		if ((_allFileHaveLeadingZeroInChromNames == YES && !zeroVal) || (_allFileHaveLeadingZeroInChromNames == NO && zeroVal)) {
722			nameConventionWarning(record, _fileNames[fileIdx], " has a record where naming convention (leading zero) is inconsistent with other files:\n");
723		}
724	
725		if (_allFileHaveLeadingZeroInChromNames == UNTESTED) {
726			_allFileHaveLeadingZeroInChromNames = zeroVal ? YES : NO;
727		}
728	}
