51	void BlockMgr::getBlocksFromBed12(RecordKeyVector &keyList, bool &mustDelete)
52	{
53		const Bed12Interval *keyRecord = static_cast<const Bed12Interval *>(keyList.getKey());
54		int blockCount = keyRecord->getBlockCount();
55	
56	    if ( blockCount <= 0 ) {
57	    	mustDelete = false;
58	    	return;
59	    }
60	
61	    int sizeCount = _blockSizeTokens.tokenize(keyRecord->getBlockSizes(), ',');
62	    int startCount = _blockStartTokens.tokenize(keyRecord->getBlockStarts(), ',');
63	
64	    if (blockCount != sizeCount || sizeCount != startCount) {
65	    	fprintf(stderr, "Error: found wrong block counts while splitting entry.\n");
66	    	exit(-1);
67	    }
68	
69	    for (int i=0; i < blockCount; i++) {
70	    	CHRPOS startPos = keyRecord->getStartPos() + str2chrPos(_blockStartTokens.getElem(i).c_str());
71	    	CHRPOS endPos = startPos + str2chrPos(_blockSizeTokens.getElem(i).c_str());
72	
73	    	Record *record = allocateAndAssignRecord(keyRecord, startPos, endPos);
74	    	keyList.push_back(record);
75	    }
76	    mustDelete = true;
77	}
