69	void NewChromSweep::closeOut(bool testChromOrderVal) {
70	    if (_testLastQueryRec) {
71	        testChromOrder(_currQueryRec);
72	    }
73	    while (!_queryFRM->eof()) {
74	        nextRecord(true);
75	        testChromOrder(_currQueryRec);
76	        _queryFRM->deleteRecord(_currQueryRec);
77	    }
78	    if (testChromOrderVal) {
79	        testChromOrder(_currQueryRec);
80	        for (int i=0; i < _numDBs; i++) {
81	            while (!_dbFRMs[i]->eof()) {
82	                if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
83	                _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
84	                nextRecord(false, i);
85	            }
86	            if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
87	        }
88	    }
89	}
