233	bool NewChromSweep::next(RecordKeyVector &retList) {
234	    retList.clearVector();
235	
236	    //make sure the first read of the query file is tested for chrom sort order.
237	    bool needTestSortOrder = false;
238	    if (_currQueryRec != NULL) {
239	        _queryFRM->deleteRecord(_currQueryRec);
240	    } else {
241	        needTestSortOrder = true;
242	    }
243	
244	    if (!nextRecord(true)) { // query EOF hit
245	        return false; 
246	    }
247	
248	    retList.setKey(_currQueryRec);
249	
250	    if (needTestSortOrder) testChromOrder(_currQueryRec);
251	
252	    if (allCurrDBrecsNull() && allCachesEmpty() && !_runToQueryEnd) {
253	        _testLastQueryRec = true;
254	        return false;
255	    }
256	    _currQueryChromName = _currQueryRec->getChrName();
257	
258	    masterScan(retList);
259	
260	    if (_context->getSortOutput()) {
261	        retList.sortVector();
262	    }
263	
264	    _prevQueryChromName = _currQueryChromName;
265	    return true;
266	}
