328	void NewChromSweep::testChromOrder(const Record *rec)
329	{
330	    // Only use this method if we don't have a genome file
331	    // and the record is valid
332	    if (_context->hasGenomeFile() || rec == NULL) return;
333	
334	    int fileIdx = rec->getFileIdx();
335	
336	    const string &chrom = rec->getChrName();
337	
338	    findChromOrder(rec);
339	
340	    //determine what the previous chrom was for this file.
341	    map<int, string>::iterator prevIter = _filePrevChrom.find(fileIdx);
342	    if (prevIter == _filePrevChrom.end()) {
343	        _filePrevChrom[fileIdx] = chrom;
344	        return; //no previously stored chrom for this file.
345	    }
346	    const string prevChrom(prevIter->second);
347	    _filePrevChrom[fileIdx] = chrom;
348	
349	    if (chrom == prevChrom) return;
350	
351	    if (verifyChromOrderMismatch(chrom, prevChrom, fileIdx)) {
352	        fprintf(stderr, "ERROR: chromomsome sort ordering for file %s is inconsistent with other files. Record was:\n", _context->getInputFileName(fileIdx).c_str());
353	        rec->print(stderr, true);
354	        exit(1);
355	    }
356	
357	    if (!_lexicoDisproven && chrom < prevChrom) {
358	        if (_lexicoAssumed) {
359	            // ERROR.
360	            fprintf(stderr, "ERROR: Sort order was unspecified, and file %s is not sorted lexicographically.\n",
361	                    _context->getInputFileName(fileIdx).c_str());
362	            fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
363	            exit(1);
364	        }
365	        _lexicoDisproven = true;
366	    }
367	}
