369	bool NewChromSweep::queryChromAfterDbRec(const Record *dbRec)
370	{
371	    //If using a genome file, compare chrom ids.
372	    //Otherwise, compare global order, inserting as needed.
373	    if (_context->hasGenomeFile()) {
374	        return (_currQueryRec->getChromId() > dbRec->getChromId()) ;
375	    }
376	    //see if query has both
377	    const string &qChrom = _currQueryRec->getChrName();
378	    const string &dbChrom = dbRec->getChrName();
379	    const _orderTrackType *track = _fileTracks[_currQueryRec->getFileIdx()];
380	    _orderTrackType::const_iterator iter = track->find(qChrom);
381	
382	
383	    int qOrder = iter->second;
384	    iter = track->find(dbChrom);
385	    if (iter == track->end()) {
386	        //query file does not contain the dbChrom.
387	        //try a lexicographical comparison, if possible.
388	        return testLexicoQueryAfterDb(_currQueryRec, dbRec);
389	    }
390	    int dbOrder = iter->second;
391	
392	    return (qOrder > dbOrder);
393	}
