434	void NewChromSweep::testThatAllDbChromsExistInQuery()
435	{
436	    if (_context->hasGenomeFile() || !_lexicoDisproven) return;
437	
438	    int queryIdx = _context->getQueryFileIdx();
439	    //get the query file track. Then check that every chrom in every db exists in it.
440	    const _orderTrackType *qTrack = _fileTracks[queryIdx];
441	
442	    for (int i=0; i < _numFiles; i++) {
443	        if (i == queryIdx) continue;
444	        const _orderTrackType *dbTrack = _fileTracks[i];
445	        for (_orderTrackType::const_iterator iter = dbTrack->begin(); iter != dbTrack->end(); iter++) {
446	            const string &chrom = iter->first;
447	            if (qTrack->find(chrom) == qTrack->end()
448	                && !chrom.empty())  // don't raise an error if the chrom is unknown (e.g., unmapped BAM)
449	            {
450	                fprintf(stderr, "ERROR: Database file %s contains chromosome %s, but the query file does not.\n",
451	                        _context->getInputFileName(i).c_str(), chrom.c_str());
452	                fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
453	                exit(1);
454	            }
455	        }
456	    }
457	}
