87	bool RecordOutputMgr::printKeyAndTerminate(RecordKeyVector &keyList) {
88		if (_context->getProgram() == ContextBase::MERGE) {
89			//when printing merged records, we want to force the printing into
90			//bed3 format, which is surprisingly difficult to do. Had to use the following:
91			const Bed3Interval *bed3 = static_cast<const Bed3Interval *>(keyList.getKey());
92			bed3->Bed3Interval::print(_outBuf);
93			return false;
94		}
95		printBamType bamCode = printBamRecord(keyList);
96		if (bamCode == BAM_AS_BAM) {
97			return true;
98		} else if (bamCode == NOT_BAM) {
99			keyList.getKey()->print(_outBuf);
100			return false;
101		}
102		//otherwise, it was BAM_AS_BED, and the key was printed.
103		return false;
104	
105	}
