107	RecordOutputMgr::printBamType RecordOutputMgr::printBamRecord(RecordKeyVector &keyList, bool bamOutputOnly)
108	{
109		const Record *record = keyList.getKey();
110		if (record->getType() == FileRecordTypeChecker::BAM_RECORD_TYPE) {
111			if (_context->getOutputFileType() == FileRecordTypeChecker::BAM_FILE_TYPE) {
112				_bamWriter->SaveAlignment(static_cast<const BamRecord *>(record)->getAlignment());
113				return BAM_AS_BAM;
114			} else {
115				if (!bamOutputOnly) {
116					if (record->isUnmapped()) {
117						record->printUnmapped(_outBuf);
118					} else {
119						static_cast<const BamRecord *>(record)->print(_outBuf, _currBamBlockList);
120					}
121				}
122				return BAM_AS_BED;
123			}
124		}
125		return NOT_BAM;
126	}
