153	void RecordOutputMgr::printClosest(RecordKeyVector &keyList, const vector<CHRPOS> *dists) {
154	
155		//The first time we print a record is when we print any header, because the header
156		//hasn't been read from the query file until after the first record has also been read.
157		checkForHeader();
158	
159		const ContextClosest *context = static_cast<const ContextClosest *>(_context);
160		bool deleteBlocks = false;
161		Record *keyRec = keyList.getKey();
162		RecordKeyVector blockList(keyRec);
163		if (keyRec->getType() == FileRecordTypeChecker::BAM_RECORD_TYPE) {
164			_bamBlockMgr->getBlocks(blockList, deleteBlocks);
165			_currBamBlockList = &blockList;
166		}
167		if (!keyList.empty()) {
168			int distCount = 0;
169			for (RecordKeyVector::iterator_type iter = keyList.begin(); iter != keyList.end(); iter = keyList.next()) {
170				const Record *hitRec = *iter;
171				printKey(keyRec, keyRec->getStartPosStr(), keyRec->getEndPosStr());
172				tab();
173				addDbFileId(hitRec->getFileIdx());
174				printKey(hitRec, hitRec->getStartPosStr(), hitRec->getEndPosStr());
175				if (dists != NULL) {
176					tab();
177					CHRPOS dist = (*dists)[distCount];
178					//if not using sign distance, use absolute value instead.
179					dist = context->signDistance() ? dist : abs(dist);
180					ostringstream s;
181					s << dist;
182					_outBuf.append(s.str());
183					distCount++;
184				}
185				newline();
186				if (needsFlush()) flush();
187			}
188		} else {
189			printKey(keyRec, keyRec->getStartPosStr(), keyRec->getEndPosStr());
190			tab();
191			// need to add a dummy file id if multiple DB files are used
192			if (_context->getNumInputFiles() > 2) {
193				_outBuf.append(".");
194				tab();
195			}		
196			null(false, true);
197			if (context->reportDistance()) {
198				tab();
199	
200				_outBuf.append("-1");
201			}
202			newline();
203		}
204		if (deleteBlocks) {
205			_bamBlockMgr->deleteBlocks(blockList);
206			_currBamBlockList = NULL;
207		}
208		return;
209	}
