227	void RecordOutputMgr::printRecord(RecordKeyVector &keyList, RecordKeyVector *blockList)
228	{
229		if (needsFlush()) {
230			flush();
231		}
232	
233		//The first time we print a record is when we print any header, because the header
234		//hasn't been read from the query file until after the first record has also been read.
235		checkForHeader();
236	
237		const_cast<Record *>(keyList.getKey())->undoZeroLength();
238		_currBamBlockList = blockList;
239	
240		if (_context->getProgram() == ContextBase::INTERSECT || _context->getProgram() == ContextBase::SUBTRACT) {
241			if (_printable) {
242				if (keyList.empty()) {
243					if ((static_cast<ContextIntersect *>(_context))->getWriteAllOverlap())
244					{
245						// -wao the user wants to force the reporting of 0 overlap
246						if (printKeyAndTerminate(keyList)) {
247							_currBamBlockList = NULL;
248							const_cast<Record *>(keyList.getKey())->adjustZeroLength();
249	
250							return;
251						}
252						tab();
253						// need to add a dummy file id if multiple DB files are used
254						if (_context->getNumInputFiles() > 2) {
255							_outBuf.append(".");
256							tab();
257						}
258						null(false, true);
259						tab();
260						_outBuf.append("0");
261						newline();
262						if (needsFlush()) flush();
263					}
264					else if ((static_cast<ContextIntersect *>(_context))->getLeftJoin()) 
265					{
266						if (printKeyAndTerminate(keyList)) {
267							_currBamBlockList = NULL;
268	
269							const_cast<Record *>(keyList.getKey())->adjustZeroLength();
270							return;
271						}
272						tab();
273						// need to add a dummy file id if multiple DB files are used
274						if (_context->getNumInputFiles() > 2) {
275							_outBuf.append(".");
276							tab();
277						}
278						null(false, true);
279						newline();
280						if (needsFlush()) flush();
281						_currBamBlockList = NULL;
282	
283						return;
284					}
285				} 
286				else 
287				{
288					if (printBamRecord(keyList, true) == BAM_AS_BAM) {
289						_currBamBlockList = NULL;
290	
291						const_cast<Record *>(keyList.getKey())->adjustZeroLength();
292						return;
293					}
294					int hitIdx = 0;
295					for (RecordKeyVector::iterator_type iter = keyList.begin(); iter != keyList.end(); iter = keyList.next()) 
296					{
297						// a hit can be invalid if there was no enough overlap, etc.
298						//if ((*iter)->isValid())
299						//{
300							reportOverlapDetail(keyList.getKey(), *iter, hitIdx);
301							hitIdx++;
302						//}
303					}
304				}
305			} else { // not printable
306				reportOverlapSummary(keyList);
307			}
308			_currBamBlockList = NULL;
309		} else if (_context->getProgram() == ContextBase::SAMPLE) {
310			if (!printKeyAndTerminate(keyList)) {
311				newline();
312			}
313		} else { // if (_context->getProgram() == ContextBase::MAP || _context->getProgram() == ContextBase::MERGE) {
314			printKeyAndTerminate(keyList);
315		}
316		_currBamBlockList = NULL;
317		const_cast<Record *>(keyList.getKey())->adjustZeroLength();
318	
319	}
