321	void RecordOutputMgr::checkForHeader() {
322		// Do we need to print a header?
323		if (!_context->getPrintHeader()) return;
324	
325		//If the tool is groupBy, and outheader was set,  but the header is empty, we need to print groupBy's
326		//default header
327		if (_context->getProgram() == ContextBase::GROUP_BY) {
328			const string &header = _context->getFile(0)->getHeader();
329			if (header.empty()) {
330				const string &defaultHeader = (static_cast<ContextGroupBy *>(_context))->getDefaultHeader();
331				_outBuf.append(defaultHeader);
332			} else {
333				_outBuf.append(header);
334			}
335		} else if (_context->hasIntersectMethods()) {
336			//if the tool is based on intersection, we want the header from the query file.
337	
338			int queryIdx = (static_cast<ContextIntersect *>(_context))->getQueryFileIdx();
339			const string &header  = _context->getFile(queryIdx)->getHeader();
340			_outBuf.append(header);
341		} else {
342			_outBuf.append(_context->getFile(0)->getHeader());
343		}
344	
345		_context->setPrintHeader(false);
346		flush();
347	}
