349	void RecordOutputMgr::reportOverlapDetail(const Record *keyRecord, const Record *hitRecord, int hitIdx)
350	{
351	
352		// overlap interval is defined by min(e1,e2) - max(s1,s2)
353		CHRPOS maxStart = max(keyRecord->getStartPos(), hitRecord->getStartPos());
354		//cout << keyRecord->getStartPos() << "," << hitRecord->getStartPos();
355		CHRPOS minEnd = min(keyRecord->getEndPos(), hitRecord->getEndPos());
356	
357		// need to undo our conversion of 1-based start coordinates to 0-based
358		if (!keyRecord->isZeroBased())
359			maxStart++;
360	
361		// all of the different printing scenarios based upon the options used.
362		if (!(static_cast<ContextIntersect *>(_context))->getWriteA() && !(static_cast<ContextIntersect *>(_context))->getWriteB()
363				&& !(static_cast<ContextIntersect *>(_context))->getWriteOverlap() && !(static_cast<ContextIntersect *>(_context))->getLeftJoin()) {
364			const_cast<Record *>(keyRecord)->undoZeroLength();
365			printKey(keyRecord, maxStart, minEnd);
366		}
367		else if (((static_cast<ContextIntersect *>(_context))->getWriteA() &&
368				(static_cast<ContextIntersect *>(_context))->getWriteB()) || (static_cast<ContextIntersect *>(_context))->getLeftJoin()) {
369			const_cast<Record *>(keyRecord)->undoZeroLength();
370			printKey(keyRecord);
371			tab();
372			const_cast<Record *>(hitRecord)->undoZeroLength();
373			addDbFileId(hitRecord->getFileIdx());
374			hitRecord->print(_outBuf);
375		}
376		else if ((static_cast<ContextIntersect *>(_context))->getWriteA()) {
377			const_cast<Record *>(keyRecord)->undoZeroLength();
378			printKey(keyRecord);
379		}
380		else if ((static_cast<ContextIntersect *>(_context))->getWriteB()) {
381			printKey(keyRecord, maxStart, minEnd);
382			tab();
383			addDbFileId(hitRecord->getFileIdx());
384			const_cast<Record *>(hitRecord)->undoZeroLength();
385			hitRecord->print(_outBuf);
386		}
387		else if ((static_cast<ContextIntersect *>(_context))->getWriteOverlap()) {
388			int overlapBases = 0;
389			if (_context->getObeySplits()) {
390				overlapBases = _context->getSplitBlockInfo()->getOverlapBases(hitIdx);
391			} else {
392				// if one of the records was zerolength, the number of
393				// overlapping bases needs to be corrected 
394				if (keyRecord->isZeroLength() || hitRecord->isZeroLength())
395				{
396					maxStart++;
397					minEnd--;
398				}
399				overlapBases = minEnd - maxStart;
400				// add one to overlapBases since we decremented minStart
401				// for 1-based records.
402				if (!keyRecord->isZeroBased())
403					overlapBases++;
404			}
405			const_cast<Record *>(keyRecord)->undoZeroLength();
406			printKey(keyRecord);
407			tab();
408			addDbFileId(hitRecord->getFileIdx());
409			const_cast<Record *>(hitRecord)->undoZeroLength();
410			hitRecord->print(_outBuf);
411			tab();
412			int2str(overlapBases, _outBuf, true);
413		}
414		newline();
415	    if (needsFlush()) flush();
416		const_cast<Record *>(hitRecord)->adjustZeroLength();
417	}
418	
419	void RecordOutputMgr::reportOverlapSummary(RecordKeyVector &keyList)
420	{
421		int numOverlapsFound = (int)keyList.size();
422		if ((static_cast<ContextIntersect *>(_context))->getAnyHit() && numOverlapsFound > 0) {
423			if (printKeyAndTerminate(keyList)) {
424				return;
425			}
426			newline();
427			if (needsFlush()) flush();
428		} else if ((static_cast<ContextIntersect *>(_context))->getWriteCount()) {
429			if (printKeyAndTerminate(keyList)) {
430				return;
431			}
432			tab();
433			int2str(numOverlapsFound, _outBuf, true);
434			newline();
435			if (needsFlush()) flush();
436		} else if ((static_cast<ContextIntersect *>(_context))->getNoHit() && numOverlapsFound == 0) {
437			if (printKeyAndTerminate(keyList)) {
438				return;
439			}
440			newline();
441			if (needsFlush()) flush();
442		}
443	}
