445	void RecordOutputMgr::addDbFileId(int fileId) {
446		ostringstream s;
447		if ((static_cast<ContextIntersect *>(_context))->getNumDatabaseFiles()  == 1) return;
448		if (!_context->getUseDBnameTags() && (!_context->getUseDBfileNames())) {
449			s << fileId;
450		} else if (_context->getUseDBnameTags()){
451			s << (static_cast<ContextIntersect *>(_context))->getDatabaseNameTag((static_cast<ContextIntersect *>(_context))->getDbIdx(fileId));
452		} else {
453			s << _context->getInputFileName(fileId);
454		}
455		_outBuf.append(s.str());
456		tab();
457	}
