459	void RecordOutputMgr::null(bool queryType, bool dbType)
460	{
461		FileRecordTypeChecker::RECORD_TYPE recordType = FileRecordTypeChecker::UNKNOWN_RECORD_TYPE;
462		if (_context->hasIntersectMethods()) {
463			if (queryType) {
464				recordType = (static_cast<ContextIntersect *>(_context))->getQueryRecordType();
465			} else if (dbType) {
466				recordType = (static_cast<ContextIntersect *>(_context))->getDatabaseRecordType(0);
467			}
468		} else  {
469			recordType = _context->getFile(0)->getRecordType();
470		}
471		//This is kind of a hack. Need an instance of the correct class of record in order to call it's printNull method.
472		Record *dummyRecord = NULL;
473		switch (recordType) {
474		case FileRecordTypeChecker::BED3_RECORD_TYPE:
475			dummyRecord = new Bed3Interval();
476			break;
477		case FileRecordTypeChecker::BED4_RECORD_TYPE:
478			dummyRecord = new Bed4Interval();
479			break;
480		case FileRecordTypeChecker::BEDGRAPH_RECORD_TYPE:
481			dummyRecord = new BedGraphInterval();
482			break;
483		case FileRecordTypeChecker::BED5_RECORD_TYPE:
484			dummyRecord = new Bed5Interval();
485			break;
486		case FileRecordTypeChecker::BED6_RECORD_TYPE:
487			dummyRecord = new Bed6Interval();
488			break;
489		case FileRecordTypeChecker::BED12_RECORD_TYPE:
490			dummyRecord = new Bed12Interval();
491			break;
492		case FileRecordTypeChecker::BED_PLUS_RECORD_TYPE:
493			dummyRecord = new BedPlusInterval();
494			(static_cast<BedPlusInterval *>(dummyRecord))->setNumPrintFields((static_cast<ContextIntersect *>(_context))->getMaxNumDatabaseFields());
495			break;
496		case FileRecordTypeChecker::BED6_PLUS_RECORD_TYPE:
497			dummyRecord = new BedPlusInterval();
498			(static_cast<BedPlusInterval *>(dummyRecord))->setNumPrintFields((static_cast<ContextIntersect *>(_context))->getMaxNumDatabaseFields());
499			break;
500		case FileRecordTypeChecker::VCF_RECORD_TYPE:
501			dummyRecord = new VcfRecord();
502			(static_cast<VcfRecord *>(dummyRecord))->setNumPrintFields((static_cast<ContextIntersect *>(_context))->getMaxNumDatabaseFields());
503			break;
504		case FileRecordTypeChecker::BAM_RECORD_TYPE:
505			dummyRecord = new BamRecord();
506			break;
507		case FileRecordTypeChecker::GFF_RECORD_TYPE:
508			dummyRecord = new GffRecord();
509			(static_cast<GffRecord *>(dummyRecord))->setNumFields((static_cast<ContextIntersect *>(_context))->getMaxNumDatabaseFields());
510			break;
511		case FileRecordTypeChecker::GFF_PLUS_RECORD_TYPE:
512			dummyRecord = new GffPlusRecord();
513			(static_cast<GffRecord *>(dummyRecord))->setNumFields((static_cast<ContextIntersect *>(_context))->getMaxNumDatabaseFields());
514			break;
515		default:
516			dummyRecord = new Bed3Interval();
517			break;
518		}
519		if (dummyRecord) {
520			dummyRecord->printNull(_outBuf);
521			delete dummyRecord;
522		}
523	}
