146	void BamRecord::printRemainingBamFields(string &outBuf, RecordKeyVector *keyList) const
147	{
148		ostringstream s;
149	    s << "\t";
150	    s << _startPosStr;
151	    s << "\t";
152	    s << _endPos;
153	    s << "\t0,0,0";
154	    s << "\t";
155	
156	    int numBlocks = (int)keyList->size();
157	
158	    if (numBlocks > 0) {
159	            s << numBlocks;
160	
161	            vector<int> blockLengths;
162	            vector<int> blockStarts;
163	            for (RecordKeyVector::iterator_type iter = keyList->begin(); iter != keyList->end(); iter = keyList->next()) {
164	                    const Record *block = *iter;
165	                    blockLengths.push_back((int)(block->getEndPos() - block->getStartPos()));
166	                    blockStarts.push_back((int)(block->getStartPos() - _startPos));
167	            }
168	
169	            s << "\t";
170	            for (int i=0; i < (int)blockLengths.size(); i++) {
171	                    s << blockLengths[i];
172	                    s << ',';
173	            }
174	            s << "\t";
175	            for (int i=0; i < (int)blockStarts.size(); i++) {
176	                    s <<  blockStarts[i];
177	                    s << ',';
178	            }
179	    }
180	    else {
181	            s << "1\t0,\t0,";
182	    }
183	    outBuf.append(s.str());
184	}
