189	    s << "\t-1\t-1\t";
190	    s << (_name.empty() ? "." : _name);
191	    s << "\t";
192	    s << (_score.empty() ? "." : _score);
193	    s << "\t.\t-1\t-1\t-1\t0,0,0\t0\t.\t."; // dot for strand, -1 for blockStarts and blockEnd
194	    outBuf.append(s.str());
195	}
