197	const string &BamRecord::getField(int fieldNum) const
198	{
199		// Unlike other records, Bam records should return the fields specified in
200		// in the BAM spec. In order, they are:
201	//	1 - QNAME 	Query template NAME
202	//	2 - FLAG	bitwise Flag
203	//	3 - RNAME	Reference sequence NAME
204	//	4 - POS		1-based left most mapping POSition
205	//	5 - MAPQ	MAPping Quality
206	//	6 - CIGAR	CIGAR String
207	//	7 - RNEXT	Ref name of the mate/NEXT read
208	//	8 - PNEXT	Position of the mate/NEXT read
209	//	9 - TLEN	observed Template LENgth
210	//	10 - SEQ	segement SEQuence
211	//	11 - QUAL	ASCII of Phred-scaled base QUALity+33
212	
213		switch (fieldNum) {
214		case 1:
215			return _name;
216			break;
217		case 2:
218			// TBD - right now, there isn't a direct way to get the flag field.
219			// Context will have to error out if they try.
220			break;
221		case 3:
222			return _chrName;
223			break;
224		case 4:
225			return _startPosStr;
226			break;
227		case 5:
228			return _score;
229			break;
230		case 6:
231			return getCigarStr();
232			break;
233		case 7:
234			return _mateChrName;
235			break;
236		case 8:
237			return _matePos;
238			break;
239		case 9:
240			return _insertSize;
241			break;
242		case 10:
243			return _queryBases;
244			break;
245		case 11:
246			return _qualities;
247			break;
248		default:
249			cerr << "***** Error: requested invalid field number " << fieldNum << " from BAM file." << endl;
250			exit(1);
251			break;
252		}
253	
254		// control can never reach here, but compiler is complaining about
255		// reaching end of non-void function, so this dummy statement will
256		// keep it happy.
257		return _name;
258	}
