267	void BamRecord::buildCigarStr() {
268	
269		const vector<BamTools::CigarOp> &cigarData = _bamAlignment.CigarData;
270		size_t cigarVecLen = cigarData.size();
271		_cigarStr.clear();
272	
273		static char* buffer = NULL;
274		static size_t buffer_size = 0;
275	
276		size_t new_buffer_size = buffer_size;
277	
278		while(new_buffer_size < cigarVecLen * 11)
279			new_buffer_size = new_buffer_size == 0 ? 128 : new_buffer_size * 2;
280	
281		if(new_buffer_size != buffer_size)
282		{
283			free(buffer);
284			buffer = (char*)malloc(new_buffer_size + 1);
285			buffer_size = new_buffer_size;
286		}
287	
288	
289		if(cigarVecLen)
290		{
291			char* ptr = buffer + buffer_size - 1;
292			ptr[1] = 0;
293	
294			for (size_t i = cigarVecLen ; i > 0; i--) {
295				for(uint32_t val = cigarData[i - 1].Length; val > 0; val /= 10)
296					*ptr-- = (val % 10) + '0';
297				if(cigarData[i - 1].Length == 0)
298					*ptr-- = '0';
299				*ptr-- = cigarData[i - 1].Type;
300			}
301	
302			_cigarStr.assign(ptr + 1, buffer + buffer_size - 1 - ptr);
303		}
304	}
