307	CHRPOS BamRecord::getLength(bool obeySplits) const {
308		//only bed12 and BAM need to check splits
309		if (!obeySplits) {
310			return _endPos - _startPos;
311		} else {
312			int length = 0;
313	    	//parse the Cigar Data.
314			const vector<BamTools::CigarOp> &cigarData = _bamAlignment.CigarData;
315		    for (int i=0; i < (int)cigarData.size(); i++) {
316		    	char op = cigarData[i].Type;
317		    	if (op == 'M' || op == 'N' || op == 'I') {
318		    		length += (int)cigarData[i].Length;
319		    	}
320		    }
321		    return (CHRPOS)length;
322		}
323	}
