52	void SubtractFile::subtractHits(RecordKeyVector &hits) {
53		if (hits.empty()) {
54	        // no intersection, nothing to subtract.
55	        // just copy key to hits as if it were a
56	        // self-intersection. This is just for reporting
57	        // purposes.
58	        hits.push_back(hits.getKey());
59			return;
60		}
61	
62		if (upCast(_context)->getRemoveAll() && upCast(_context)->getSubtractFraction() == 0.0) {
63			// hits aren't empty, meaning there is intersection,
64			// so we want to not report the hit.
65			_dontReport = true;
66			return;
67		}
68	
69		//loop through hits. Track which bases in query were covered
70		Record *keyRec = hits.getKey();
71		int keyStart = keyRec->getStartPos();
72		int keyEnd = keyRec->getEndPos();
73	
74		//this vector of bools will represent the bases of the query.
75		//for each base, true means uncovered, false means covered.
76		//they begin as all uncovered.
77		vector<bool> keyBases(keyEnd - keyStart, true);
78	
79		//now loop through the hits, and cover corresponding query bases
80		//by setting them to false.
81		bool basesRemoved = false;
82		for (RecordKeyVector::iterator_type iter = hits.begin(); iter != hits.end(); iter = hits.next()) {
83			Record *hitRec = *iter;
84			int hitStart = hitRec->getStartPos();
85			int hitEnd = hitRec->getEndPos();
86	
87			int startIdx = max(keyStart, hitStart) - keyStart;
88			int endIdx = min(keyEnd, hitEnd) - keyStart;
89	
90			int keyLen = keyEnd - keyStart;
91			int coveredLen = endIdx - startIdx;
92			float coveragePct = (float)coveredLen / (float)keyLen;
93			//for each base in the hit, set the base in the query to false.
94			//this effectively "erases" the covered bits. Only do
95			if (upCast(_context)->getRemoveSum() || coveragePct >= upCast(_context)->getSubtractFraction()) {
96				std::fill(keyBases.begin() + startIdx, keyBases.begin() + endIdx, false);
97				basesRemoved = true;
98			}
99		}
100	
101		if (!basesRemoved) {
102			//treat as if there were no intersection
103			hits.clearVector();
104			hits.push_back(hits.getKey());
105			return;
106		} else if (upCast(_context)->getRemoveAll()) {
107			_dontReport = true;
108			return;
109		}
110		// if the -N option is used ( removeSum), do not report if the percentage of
111		// uniquely covered bases exceeds the overlap fraction.
112		if (upCast(_context)->getRemoveSum()) {
113			//determine how many bases are left uncovered.
114			int numBasesUncovered = std::accumulate(keyBases.begin(), keyBases.end(), 0);
115			//determine percentage that are covered.
116			float pctCovered = 1.0 - (float)numBasesUncovered / (float)(keyEnd - keyStart);
117			if (pctCovered > upCast(_context)->getSubtractFraction()) {
118				_dontReport = true;
119				return;
120			} else {
121	            hits.clearVector();
122	            hits.push_back(hits.getKey());
123	        }
124			return;
125		}
126	
127		//now make "blocks" out of the query's remaining stretches of
128		//uncovered bases.
129		hits.clearVector();
130	    for (int i = 0; i < (int)keyBases.size(); i++) {
131	        if (keyBases[i] == true) {
132	            int blockStart = keyStart + i;
133	            while (keyBases[i] == true && i < (int)keyBases.size()) {
134	                i++;
135	            }
136	            int blockEnd = min(keyStart + i, keyEnd);
137	            hits.push_back(_tmpBlocksMgr->allocateAndAssignRecord(keyRec, blockStart, blockEnd));
138	        }
139	    }
140	    _deleteTmpBlocks = true;
141	
142	}
