35	void ComplementFile::processHits(RecordOutputMgr *outputMgr, RecordKeyVector &hits)
36	{
37		_outputMgr = outputMgr;
38		const Record *rec = hits.getKey();
39	
40		//test for chrom change.
41		const string &newChrom = rec->getChrName();
42		if (_currChrom != newChrom) {
43	
44			outPutLastRecordInPrevChrom();
45	
46			//if record's chrom doesn't exist in the genome file, do
