96	void ComplementFile::outPutLastRecordInPrevChrom()
97	{
98		const string &chrom = _outRecord.getChrName();
99	
100		//do nothing if triggered by first record in DB. At this point,
101		//there was no prev chrom, so nothing is stored in the output Record yet.
102		if (chrom.empty()) return;
103		CHRPOS maxChromSize = _genomeFile->getChromSize(chrom);
104		if (_currStartPos >= maxChromSize) return; //chrom already covered and reported.
