109	bool ComplementFile::fastForward(const string &newChrom) {
110		if (!newChrom.empty() && !_genomeFile->hasChrom(newChrom)) return false;
111	
112		int i= _currPosInGenomeList +1;
113		while (i < (int)_chromList.size() && _chromList[i] != newChrom) {
114			_outRecord.setChrName(_chromList[i]);
115			_currStartPos = 0;
116			CHRPOS endPos = _genomeFile->getChromSize(_chromList[i]);
117			printRecord(endPos);
118			i++;
119		}
120		if (newChrom.empty()) return true;
121	
122		if (i== (int)_chromList.size()) {
123			//reached end but didn't find new chrom. Genome and DB are not sorted in same order.
124			cerr << "***** ERROR: genome file and input file are not sorted in same order. Exiting..." << endl;
125			exit(1);
126			//this is where we'd return false if we weren't exiting.
127		}
128		_currChrom = newChrom;
129		_currPosInGenomeList = i;
130		return true;
131	}
