133	void ComplementFile::printRecord(CHRPOS endPos)
134	{
135		_outRecord.setStartPos(_currStartPos);
136		stringstream startStr;
137		startStr << _currStartPos;
138		_outRecord.setStartPosStr(startStr.str());
139	
140		_outRecord.setEndPos(endPos);
141		stringstream endStr;
142		endStr << endPos;
143		_outRecord.setEndPosStr(endStr.str());
144	
145		_outputMgr->printRecord(&_outRecord);
146		_outputMgr->newline();
147	
148	}
