namespace {

bool blockFractionPasses(CHRPOS overlapBases, CHRPOS totalLength, float fraction) {
	if (fraction <= 0.0f) {
		return overlapBases > 0;
	}
	if (totalLength <= 0) {
		return false;
	}
	return ((float)overlapBases / (float)totalLength) >= fraction;
}

CHRPOS unionOfOverlapIntervals(vector<pair<CHRPOS, CHRPOS> > &intervals) {
	if (intervals.empty()) {
		return 0;
	}
	sort(intervals.begin(), intervals.end());

	CHRPOS unionLength = 0;
	CHRPOS currStart = intervals[0].first;
	CHRPOS currEnd = intervals[0].second;
	for (size_t i = 1; i < intervals.size(); i++) {
		if (intervals[i].first <= currEnd) {
			if (intervals[i].second > currEnd) {
				currEnd = intervals[i].second;
			}
		} else {
			unionLength += currEnd - currStart;
			currStart = intervals[i].first;
			currEnd = intervals[i].second;
		}
	}
	unionLength += currEnd - currStart;
	return unionLength;
}

} // namespace

