			RecordKeyVector::iterator_type keyListIter = keyList.begin();
			for (; keyListIter != keyList.end(); keyListIter = keyList.next())
			{
				const Record *keyBlock = *keyListIter;
				const Record *hitBlock = *hitBlockIter;

				CHRPOS maxStart = max(keyBlock->getStartPos(), hitBlock->getStartPos());
				CHRPOS minEnd = min(keyBlock->getEndPos(), hitBlock->getEndPos());
				CHRPOS overlap  = minEnd - maxStart;
				if (overlap > 0) {
					hitHasOverlap = true;
					if (overlapList != NULL) {
						overlapList->push_back(allocateAndAssignRecord(keyList.getKey(), maxStart, minEnd));
					}
					totalHitOverlap += overlap;
					allOverlapIntervals.push_back(make_pair(maxStart, minEnd));
				}
			}
		}

		HitOverlapInfo hitInfo = { *hitListIter, totalHitOverlap, hitBlockSumLength, hitHasOverlap };
		hitOverlapInfo.push_back(hitInfo);

		if (deleteHitBlocks) {
			deleteBlocks(hitBlocks);
		}
	}

	CHRPOS totalQueryOverlap = unionOfOverlapIntervals(allOverlapIntervals);
	bool queryFractionPasses = blockFractionPasses(totalQueryOverlap, keyBlocksSumLength, _overlapFraction);

	for (size_t i = 0; i < hitOverlapInfo.size(); i++) {
		const HitOverlapInfo &hitInfo = hitOverlapInfo[i];
		if (!hitInfo.hitHasOverlap) {
			continue;
		}

		bool hitAFractionPasses = blockFractionPasses(hitInfo.totalHitOverlap, keyBlocksSumLength, _overlapFraction);
		bool hitBFractionPasses = blockFractionPasses(hitInfo.totalHitOverlap, hitInfo.hitBlockSumLength, overlapFractionB);

		bool keepHit = false;
		if (_hasEitherFraction) {
			// -e: the requested fraction may be satisfied by either the query
			// (as a whole) or the database record.
			keepHit = queryFractionPasses || hitBFractionPasses;
		} else if (_hasReciprocal) {
			// -r: keep the per-record reciprocal semantics.
			keepHit = hitAFractionPasses && hitBFractionPasses;
		} else {
			keepHit = queryFractionPasses && hitBFractionPasses;
		}

		if (keepHit) {
			_overlapBases.push_back((int)hitInfo.totalHitOverlap);
			resultList.push_back(hitInfo.hitRecord);
		}
	}

	if (deleteKeyBlocks) {
		deleteBlocks(keyList);
	}
	resultList.setKey(keyList.getKey());
	return (int)resultList.size();
}

