}

int BlockMgr::findBlockedOverlaps(RecordKeyVector &keyList, RecordKeyVector &hitList,
	                              RecordKeyVector &resultList, RecordKeyVector *overlapList)
{
	bool deleteKeyBlocks = false;
	if (keyList.empty()) {
		//get all the blocks for the query record, put them in it's list.
		getBlocks(keyList, deleteKeyBlocks);
	}
	_overlapBases.clear();
	resultList.clearVector();

	CHRPOS keyBlocksSumLength = getTotalBlockLength(keyList);

	// With -split, a single query record can obtain its fractional support
	// from more than one database record (for example, the two exons flanking
	// a junction).  Therefore, first collect the per-hit block overlaps and
	// the union of query block bases covered by all database records.
	// Fractional filtering is applied afterwards so that output modes such as
	// -u and -wa/-wb make the same record-level decision.
	struct HitOverlapInfo {
		Record *hitRecord;
		CHRPOS totalHitOverlap;
		CHRPOS hitBlockSumLength;
		bool hitHasOverlap;
	};
	vector<HitOverlapInfo> hitOverlapInfo;
	vector<pair<CHRPOS, CHRPOS> > allOverlapIntervals;

	float overlapFractionB = _hasReciprocal ? _overlapFraction : _overlapFractionB;

	//Loop through every database record the query intersected with
	RecordKeyVector::iterator_type hitListIter = hitList.begin();
	for (; hitListIter != hitList.end(); hitListIter = hitList.next())
	{
		RecordKeyVector hitBlocks(*hitListIter);
		bool deleteHitBlocks = false;
		getBlocks(hitBlocks, deleteHitBlocks); //get all blocks for the hit record.
		CHRPOS hitBlockSumLength = getTotalBlockLength(hitBlocks); //get total length of the bocks for the hitRecord.
		CHRPOS totalHitOverlap = 0;
		bool hitHasOverlap = false;

		//loop through every block of the database record.
		RecordKeyVector::iterator_type hitBlockIter = hitBlocks.begin();
		for (; hitBlockIter != hitBlocks.end(); hitBlockIter = hitBlocks.next())
		{
			//loop through every block of the query record.
			RecordKeyVector::iterator_type keyListIter = keyList.begin();
			for (; keyListIter != keyList.end(); keyListIter = keyList.next())
			{
				const Record *keyBlock = *keyListIter;
				const Record *hitBlock = *hitBlockIter;

				CHRPOS maxStart = max(keyBlock->getStartPos(), hitBlock->getStartPos());
				CHRPOS minEnd = min(keyBlock->getEndPos(), hitBlock->getEndPos());
				CHRPOS overlap  = minEnd - maxStart;
				if (overlap > 0) {
					hitHasOverlap = true;
					if (overlapList != NULL) {
						overlapList->push_back(allocateAndAssignRecord(keyList.getKey(), maxStart, minEnd));
					}
					totalHitOverlap += overlap;
					allOverlapIntervals.push_back(make_pair(maxStart, minEnd));
				}
			}
		}

		HitOverlapInfo hitInfo = { *hitListIter, totalHitOverlap, hitBlockSumLength, hitHasOverlap };
		hitOverlapInfo.push_back(hitInfo);

		if (deleteHitBlocks) {
			deleteBlocks(hitBlocks);
		}
	}

	CHRPOS totalQueryOverlap = unionOfOverlapIntervals(allOverlapIntervals);
	bool queryFractionPasses = blockFractionPasses(totalQueryOverlap, keyBlocksSumLength, _overlapFraction);

	for (size_t i = 0; i < hitOverlapInfo.size(); i++) {
		const HitOverlapInfo &hitInfo = hitOverlapInfo[i];
		if (!hitInfo.hitHasOverlap) {
			continue;
		}

		bool hitAFractionPasses = blockFractionPasses(hitInfo.totalHitOverlap, keyBlocksSumLength, _overlapFraction);
		bool hitBFractionPasses = blockFractionPasses(hitInfo.totalHitOverlap, hitInfo.hitBlockSumLength, overlapFractionB);

		bool keepHit = false;
		if (_hasEitherFraction) {

		if (_hasEitherFraction) {
			// -e: the requested fraction may be satisfied by either the query
			// (as a whole) or the database record.
			keepHit = queryFractionPasses || hitBFractionPasses;
		} else if (_hasReciprocal) {
			// -r: keep the per-record reciprocal semantics.
			keepHit = hitAFractionPasses && hitBFractionPasses;
		} else {
			keepHit = queryFractionPasses && hitBFractionPasses;
		}

		if (keepHit) {
			_overlapBases.push_back((int)hitInfo.totalHitOverlap);
			resultList.push_back(hitInfo.hitRecord);
		}
	}

	if (deleteKeyBlocks) {
		deleteBlocks(keyList);
	}
	resultList.setKey(keyList.getKey());
	return (int)resultList.size();
}

