15	using namespace std;
16	
17	template <class T>
18	class FreeList {
19	public:
20		FreeList(int blockSize=512)
21		: _nextPos(0),
22		  _blockSize(blockSize)
23		{
24			_freeList.reserve(_blockSize);
25		}
26	
27		~FreeList() {
28			for (int i=0; i < (int)_buffer.size(); i++) {
29				delete _buffer[i];
30			}
31		}
32	
33		void clear() {
34			_nextPos = 0;
35			_freeList.clear();
36		}
37	
38		T *newObj() {
39			T *ptr = NULL;
40	
41			if (_freeList.size() > 0) {
42				ptr = _freeList.back();
43				_freeList.pop_back();
44			} else {
45				if (_nextPos == (int)_buffer.size()) {
46					growBuffer();
47				}
48				ptr = _buffer[_nextPos];
49				_nextPos ++;
50			}
51	
52			return ptr;
53		}
54	
55		void deleteObj(const T *ptr) {
56			if (ptr != NULL) {
57				T *volatilePtr = const_cast<T *>(ptr); //remove const-ness.
58				volatilePtr->clear();
59				_freeList.push_back(volatilePtr);
60			}
61		}
62	
63		int capacity() const { return _buffer.size(); }
64	
65	private:
66		deque<T *> _buffer;
67		vector<T *> _freeList;
68		int _nextPos;
69		int _blockSize;
70		void growBuffer() {
71			for (int i=0; i < _blockSize; ++i) {
72				_buffer.push_back(new T());
73			}
74		}
75	
76		//this number determines how many times larger than the blockSize the freeList
77		//is allowed to grow. If speed performance is poor, we may need to increase this number.
78		//If memory performance is poor, decrease it.
79		static const int MAX_MULTIPLE_FREE_LIST_SIZE = 10;
80	};
